CREATE TABLE ai_usage (id uuid PRIMARY KEY, extraction_id uuid NOT NULL REFERENCES extractions(id) ON DELETE CASCADE, provider text NOT NULL, model text NOT NULL, kind text NOT NULL, metered boolean NOT NULL, prompt_tokens integer NOT NULL, cached_tokens integer NOT NULL, output_tokens integer NOT NULL, thought_tokens integer NOT NULL, total_tokens integer NOT NULL, input_usd numeric(14,8), output_usd numeric(14,8), cost_usd numeric(14,8), usd_brl_rate numeric(12,6), cost_brl numeric(14,6), created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX ai_usage_extraction ON ai_usage(extraction_id);
